const MAX_PRIVATE_PHOTO_LOADS=4;
let privatePhotoRenderTimer=0,privatePhotoLoadsActive=0,authenticatedLoadRevision=0;
const usesAuthenticatedCatalogue=()=>!SECRET_DEMO_MODE&&SHEET_ID!==DEFAULT_SHEET_ID;
