// Hand a public Drive photo URL to the user's ChatGPT Project without API usage.
const PHOTO_CLEANING_PROJECT_URL='https://chatgpt.com/g/g-p-6a46b3d92aac8191b713d358ec0a1790-toy-photos/project';
function aiCleaningSource(figure,target){const source=target==='alternate'?figure.altImage:figure.image,fileId=drivePhotoId(source);return{source,direct:fileId?`https://drive.google.com/uc?export=download&id=${encodeURIComponent(fileId)}`:source,filename:`${figureNumber(figure)}${target==='alternate'?'b':''}.png`}}
function aiCleaningPrompt(figure,target){const photo=aiCleaningSource(figure,target),label=target==='alternate'?'alternate':'main';return`Clean the ${label} catalogue photo for “${figure.name}” according to this Project's instructions.\n\nSource image (direct download):\n${photo.direct}\n\nOriginal sharing URL:\n${photo.source}\n\nMandatory output requirements:\n- Preserve the exact photographed physical minifig, printing, colors, materials, accessories, proportions, and authentic imperfections.\n- Apply only a gentle, physically plausible rotation and perspective correction so the minifig appears upright and directly front-facing. Do not invent unseen surfaces.\n- Isolate the complete minifig on a genuinely transparent background, with no floor, shadow, reflection, halo, or baked-in background color.\n- Center it with equal margins at approximately 75% of the image height.\n- Return a precise 1254 × 1254 RGBA PNG.\n- Do not redesign, recreate, idealize, or substitute any part.\n\nPlease return only the cleaned image and use this filename when downloaded: ${photo.filename}`}
function copyAiCleaningPrompt(text){const textarea=document.createElement('textarea');textarea.value=text;textarea.setAttribute('readonly','');textarea.style.cssText='position:fixed;left:-9999px;top:0';document.body.append(textarea);textarea.select();let copied=false;try{copied=document.execCommand('copy')}catch(error){console.debug('Clipboard fallback failed.',error)}textarea.remove();if(copied)return Promise.resolve(true);if(navigator.clipboard?.writeText)return navigator.clipboard.writeText(text).then(()=>true).catch(()=>false);return Promise.resolve(false)}
async function openAiPhotoCleaning(figure,target){const source=target==='alternate'?figure.altImage:figure.image;if(!source){photoManagerStatus.textContent='This photo slot is empty.';return}const prompt=aiCleaningPrompt(figure,target),copyResult=copyAiCleaningPrompt(prompt),projectTab=window.open(PHOTO_CLEANING_PROJECT_URL,'_blank');if(projectTab)projectTab.opener=null;const copied=await copyResult;photoManagerStatus.textContent=copied?'Prompt copied. Paste it into the ChatGPT Project that just opened.':'The ChatGPT Project opened, but the prompt could not be copied. Please allow clipboard access and try again.'}
function showAiCleaningChoices(figure){photoManagerDescription.textContent='Which photo do you want to clean with AI?';photoManagerActions.innerHTML=`<button type="button" class="photo-replace-choice" data-ai-photo="primary"><img src="${escapeHtml(imageSource(figure.image))}" alt="Main photo preview"><span><strong>Main photo</strong><small>Output: ${escapeHtml(figureNumber(figure))}.png</small></span><span class="material-symbols-rounded photo-replace-choice-icon" aria-hidden="true">auto_fix_high</span></button><button type="button" class="photo-replace-choice" data-ai-photo="alternate"><img src="${escapeHtml(imageSource(figure.altImage))}" alt="Alternate photo preview"><span><strong>Alternate photo</strong><small>Output: ${escapeHtml(figureNumber(figure))}b.png</small></span><span class="material-symbols-rounded photo-replace-choice-icon" aria-hidden="true">auto_fix_high</span></button><button type="button" data-photo-action="back"><span class="material-symbols-rounded">arrow_back</span><span><strong>Back</strong><small>Return to photo options</small></span></button>`}

// Keep canonical Drive sharing URLs in Sheets; cache-busting belongs only to rendered image requests.
function canonicalDrivePhotoUrl(url,fileId=''){const id=fileId||drivePhotoId(url);return id?`https://drive.google.com/file/d/${id}/view?usp=sharing`:url}
function rememberPhotoRefresh(fileId){if(fileId)photoRenderRefreshTokens.set(fileId,String(Date.now()))}
const uploadPrimaryBeforeCanonicalSharing=uploadFigurePhoto;
uploadFigurePhoto=async(file,figure)=>{let uploaded;try{uploaded=await uploadPrimaryBeforeCanonicalSharing(file,figure)}catch(error){if(!drivePhotoId(figure.image)||!/file not found|not found|404/i.test(error.message||''))throw error;const staleUrl=figure.image;figure.image='';try{uploaded=await uploadPrimaryBeforeCanonicalSharing(file,figure)}finally{figure.image=staleUrl}}if(uploaded.replaced)rememberPhotoRefresh(uploaded.fileId);uploaded.url=canonicalDrivePhotoUrl(uploaded.url,uploaded.fileId);return uploaded};
const uploadAlternateBeforeCanonicalSharing=uploadAlternateFigurePhoto;
uploadAlternateFigurePhoto=async(file,figure)=>{let uploaded;try{uploaded=await uploadAlternateBeforeCanonicalSharing(file,figure)}catch(error){if(!drivePhotoId(figure.altImage)||!/file not found|not found|404/i.test(error.message||''))throw error;const staleUrl=figure.altImage;figure.altImage='';try{uploaded=await uploadAlternateBeforeCanonicalSharing(file,figure)}finally{figure.altImage=staleUrl}}if(uploaded.replaced)rememberPhotoRefresh(uploaded.fileId);uploaded.url=canonicalDrivePhotoUrl(uploaded.url,uploaded.fileId);return uploaded};
uploadFigurePhotoTarget=(file,figure,target='primary')=>target==='alternate'?uploadAlternateFigurePhoto(file,figure):uploadFigurePhoto(file,figure);
/* GitHub's raw-file CDN can remain stale after a push; use the repository API for the About version check. */
checkAboutVersionWithoutUpdating=async function(){const latest=$('#latestAppVersion'),status=$('#aboutVersionStatus'),refresh=$('#refreshLatestVersion');if(!latest||!status||!refresh)return;latest.textContent='Checking…';status.textContent='Checking GitHub for the latest version…';refresh.disabled=true;try{const url=`https://api.github.com/repos/mreizinho/custom-minifigs-collector/contents/index.html?ref=main&_versionCheck=${Date.now()}`,response=await fetch(url,{cache:'no-store',headers:{Accept:'application/vnd.github.raw+json'}});if(!response.ok)throw Error(`GitHub version check failed (${response.status})`);const html=await response.text(),match=html.match(/app\.js\?v=([^"'&<]+)/);if(!match)throw Error('The version in GitHub could not be identified.');const githubVersion=decodeURIComponent(match[1]);latest.textContent=formatAppVersion(githubVersion);const newer=githubVersion.localeCompare(loadedAppVersion,undefined,{numeric:true})>0;status.textContent=githubVersion===loadedAppVersion?'You are using the latest GitHub version.':newer?'A newer GitHub version is available. Press the button below to update.':'This loaded version is newer than GitHub main.'}catch(error){latest.textContent='Unavailable';status.textContent=error.message}finally{refresh.disabled=false}};
